ALTER TABLE commandeclient ADD CONSTRAINT FK_commandeclient_idclient FOREIGN KEY (idclient) REFERENCES client;
ALTER TABLE commandeclient ADD CONSTRAINT FK_commandeclient_identreprise FOREIGN KEY (identreprise) REFERENCES entreprise;
CREATE INDEX IDX_commandeclient_idclient ON commandeclient (idclient);
CREATE INDEX IDX_commandeclient_identreprise ON commandeclient (identreprise);

CREATE TABLE lignecommandeclient (
