ALTER TABLE lignecommandeclient ADD CONSTRAINT FK_lignecommandeclient_idarticle FOREIGN KEY (idarticle) REFERENCES article;
ALTER TABLE lignecommandeclient ADD CONSTRAINT FK_lignecommandeclient_idcommandeclient FOREIGN KEY (idcommandeclient) REFERENCES commandeclient;
CREATE INDEX IDX_lignecommandeclient_idarticle ON lignecommandeclient (idarticle);
CREATE INDEX IDX_lignecommandeclient_idcommandeclient ON lignecommandeclient (idcommandeclient);

