ALTER TABLE commandefournisseur ADD CONSTRAINT FK_commandefournisseur_idfournisseur FOREIGN KEY (idfournisseur) REFERENCES fournisseur;
ALTER TABLE commandefournisseur ADD CONSTRAINT FK_commandefournisseur_identreprise FOREIGN KEY (identreprise) REFERENCES entreprise;
CREATE INDEX IDX_commandefournisseur_idfournisseur ON commandefournisseur (idfournisseur);
CREATE INDEX IDX_commandefournisseur_identreprise ON commandefournisseur (identreprise);

CREATE TABLE lignecommandefournisseur (
