ALTER TABLE lignecommandefournisseur ADD CONSTRAINT FK_lignecommandefournisseur_idarticle FOREIGN KEY (idarticle) REFERENCES article;
ALTER TABLE lignecommandefournisseur ADD CONSTRAINT FK_lignecommandefournisseur_idcommandefournisseur FOREIGN KEY (idcommandefournisseur) REFERENCES commandefournisseur;
CREATE INDEX IDX_lignecommandefournisseur_idarticle ON lignecommandefournisseur (idarticle);
CREATE INDEX IDX_lignecommandefournisseur_idcommandefournisseur ON lignecommandefournisseur (idcommandefournisseur);

