ALTER TABLE vente ADD CONSTRAINT FK_vente_idclient FOREIGN KEY (idclient) REFERENCES client;
ALTER TABLE vente ADD CONSTRAINT FK_vente_identreprise FOREIGN KEY (identreprise) REFERENCES entreprise;
CREATE INDEX IDX_vente_idclient ON vente (idclient);
CREATE INDEX IDX_vente_identreprise ON vente (identreprise);

