ALTER TABLE lignevente ADD CONSTRAINT FK_lignevente_idarticle FOREIGN KEY (idarticle) REFERENCES article;
ALTER TABLE lignevente ADD CONSTRAINT FK_lignevente_idvente FOREIGN KEY (idvente) REFERENCES vente;
